vec4 effect(vec2 uv) {
  vec2 w = (vec2(noise(uv * 30.0), noise(uv * 30.0 + 7.0)) - 0.5) * 0.008;
  vec3 b = blurAt(uv + w, 0.006).rgb;
  b = floor(b * 7.0 + 0.5) / 7.0;
  float e = clamp(edge(uv) * 1.5, 0.0, 1.0);
  vec3 col = mix(b, b * 0.75, e) * (0.94 + 0.06 * noise(uv * 220.0));
  return vec4(mix(getColor(uv).rgb, col, uAmount), getColor(uv).a);
}
